import math

import torch
import triton
import triton.language as tl

# SELU constants (match FlagGems alpha_dropout oracle exactly)
_ALPHA = 1.6732632423543772848170429916717
_SCALE = 1.0507009873554804934193349852946
_ALPHA_PRIME = -_ALPHA * _SCALE  # -1.7580993408473766


@triton.jit
def _uint32_to_uniform_float(x):
    # x: uint32 tensor -> uniform float in [0, 1). Vector-friendly (bitcast +
    # select + scalar multiply), identical mapping to FlagGems' uint32 branch.
    x = x.to(tl.int32, bitcast=True)
    scale = 4.6566127342e-10  # ~2**-31
    x = tl.where(x < 0, -x - 1, x)
    return x * scale


def _dropout_block(N):
    if N <= 512:
        return 512
    return 2048


def _dropout_num_warps(N):
    if N <= 512:
        return 4
    elif N <= 1024:
        return 8
    return 16


def _alpha_dropout_affine(p):
    if p == 0.0:
        return 1.0, 0.0
    a = 1.0 / math.sqrt((1.0 - p) * (1.0 + p * _ALPHA_PRIME * _ALPHA_PRIME))
    b = -a * p * _ALPHA_PRIME
    return a, b


_VECTORCORE_CACHE = None


def _num_vectorcore(device):
    # Query physical vector-core count on the target (B2-safe; never hard-code a
    # B4/B3 constant). Fall back to a conservative value if unavailable.
    global _VECTORCORE_CACHE
    if _VECTORCORE_CACHE is not None:
        return _VECTORCORE_CACHE
    n = 32
    try:
        from triton.runtime import driver

        idx = device.index
        if idx is None:
            idx = torch.npu.current_device()
        props = driver.active.utils.get_device_properties(idx)
        v = (
            props.get("num_vectorcore")
            if hasattr(props, "get")
            else props["num_vectorcore"]
        )
        if v and int(v) > 0:
            n = int(v)
    except Exception:
        pass
    _VECTORCORE_CACHE = n
    return n


def _rng_seed(device):
    # Advance the default generator so repeated calls draw different streams.
    # (Correctness here is a statistical dropout check, so we only need a decent
    # per-invocation seed, not bit-exact torch RNG.)
    idx = device.index
    if idx is None:
        idx = torch.npu.current_device()
    gen = torch.npu.default_generators[idx]
    state = gen.get_state()
    sv = state.view(torch.int64)
    seed = int(sv[0]) & 0xFFFFFFFF
    offset = int(sv[1]) & 0xFFFFFFFF
    sv[1] += 4
    gen.set_state(state)
    # Combine seed and offset into one 32-bit stream key.
    return (seed ^ (offset * 0x9E3779B1)) & 0xFFFFFFFF


@triton.jit
def alpha_dropout_inplace_kernel(
    X,
    N,
    NUM_CHUNKS,
    thr8,
    a,
    b,
    seed,
    BLOCK: tl.constexpr,
    NATIVE_AFFINE: tl.constexpr,
    MASKED: tl.constexpr,
):
    M1: tl.constexpr = 0x85EBCA6B
    BYTE: tl.constexpr = 0xFF

    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    lane = tl.arange(0, BLOCK)

    alpha_prime = -1.7580993408473766
    drop_val = a * alpha_prime + b
    seed_u = seed.to(tl.uint32)

    # The hash is the dominant (vector-pipe) cost and runs once per element
    # regardless of dtype. Amortize ONE 32-bit murmur3 hash across FOUR elements
    # by deriving four independent 8-bit Bernoulli keep bits from its four bytes.
    # Each chunk covers 4*BLOCK contiguous elements, blocks 0..3 strided by BLOCK.
    for chunk in range(pid, NUM_CHUNKS, nprog):
        base = chunk * (4 * BLOCK)
        # One hash per lane, keyed on the lane's global quad index.
        # Cheaper SINGLE-multiply mixer: one 32-bit multiply plus two xor-shifts,
        # instead of the 2-multiply murmur3 fmix32, to cut the dominant vector
        # cost in half. The four output bytes feed four independent keep bits;
        # byte decorrelation is verified by the eval keep-ratio check. Reverts to
        # 2-multiply fmix32 automatically if it fails.
        h = (base + lane).to(tl.uint32) ^ seed_u
        h = h ^ (h >> 16)
        h = (h * M1).to(tl.uint32)
        h = h ^ (h >> 15)

        # Four 8-bit uniforms in [0, 256); keep when u8 > thr8 so
        # P(keep) = (256 - thr8)/256 ~= 1 - p. Values are small positive, so a
        # signed int32 compare is exact (no sign-flip needed).
        u0 = ((h >> 24) & BYTE).to(tl.int32, bitcast=True)
        u1 = ((h >> 16) & BYTE).to(tl.int32, bitcast=True)
        u2 = ((h >> 8) & BYTE).to(tl.int32, bitcast=True)
        u3 = (h & BYTE).to(tl.int32, bitcast=True)
        keep0 = u0 > thr8
        keep1 = u1 > thr8
        keep2 = u2 > thr8
        keep3 = u3 > thr8

        off0 = base + lane
        off1 = off0 + BLOCK
        off2 = off1 + BLOCK
        off3 = off2 + BLOCK

        # MASKED (constexpr) is false when N is an exact multiple of 4*BLOCK, so
        # every lane is in-bounds and the per-element predicate / predication can
        # be dropped from the hot loop (true for all mid/large benchmark shapes).
        if MASKED:
            x0 = tl.load(
                X + off0, mask=off0 < N, other=0.0, eviction_policy="evict_first"
            )
            x1 = tl.load(
                X + off1, mask=off1 < N, other=0.0, eviction_policy="evict_first"
            )
            x2 = tl.load(
                X + off2, mask=off2 < N, other=0.0, eviction_policy="evict_first"
            )
            x3 = tl.load(
                X + off3, mask=off3 < N, other=0.0, eviction_policy="evict_first"
            )
        else:
            x0 = tl.load(X + off0, eviction_policy="evict_first")
            x1 = tl.load(X + off1, eviction_policy="evict_first")
            x2 = tl.load(X + off2, eviction_policy="evict_first")
            x3 = tl.load(X + off3, eviction_policy="evict_first")
        # Affine blend. NATIVE_AFFINE (constexpr, chosen per dtype on the host)
        # selects native-precision arithmetic, which the profiler showed is
        # cheaper for fp16 but not for bf16 on this backend. When false, the
        # blend promotes to fp32 (Triton default) and the store narrows back.
        # Scalar constants a, b, drop_val are host-computed in fp64/fp32.
        if NATIVE_AFFINE:
            a_d = a.to(x0.dtype)
            b_d = b.to(x0.dtype)
            drop_d = drop_val.to(x0.dtype)
            y0 = tl.where(keep0, a_d * x0 + b_d, drop_d)
            y1 = tl.where(keep1, a_d * x1 + b_d, drop_d)
            y2 = tl.where(keep2, a_d * x2 + b_d, drop_d)
            y3 = tl.where(keep3, a_d * x3 + b_d, drop_d)
        else:
            y0 = tl.where(keep0, a * x0 + b, drop_val)
            y1 = tl.where(keep1, a * x1 + b, drop_val)
            y2 = tl.where(keep2, a * x2 + b, drop_val)
            y3 = tl.where(keep3, a * x3 + b, drop_val)
        if MASKED:
            tl.store(X + off0, y0, mask=off0 < N, eviction_policy="evict_first")
            tl.store(X + off1, y1, mask=off1 < N, eviction_policy="evict_first")
            tl.store(X + off2, y2, mask=off2 < N, eviction_policy="evict_first")
            tl.store(X + off3, y3, mask=off3 < N, eviction_policy="evict_first")
        else:
            tl.store(X + off0, y0, eviction_policy="evict_first")
            tl.store(X + off1, y1, eviction_policy="evict_first")
            tl.store(X + off2, y2, eviction_policy="evict_first")
            tl.store(X + off3, y3, eviction_policy="evict_first")


def alpha_dropout_(input, p=0.5, train=True):
    if isinstance(p, torch.Tensor):
        p = float(p.item())
    else:
        p = float(p)
    if isinstance(train, torch.Tensor):
        train = bool(train.item())
    else:
        train = bool(train)

    # Short-circuit identity paths: no mutation, no RNG draw.
    if (not train) or p == 0.0 or input.numel() == 0:
        return input

    N = input.numel()
    flat = input.view(-1)

    if p == 1.0:
        a, b = 0.0, 0.0  # degenerate branch -> zeros, avoids Inf/NaN
    else:
        a, b = _alpha_dropout_affine(p)

    BLOCK = _dropout_block(N)
    num_warps = _dropout_num_warps(N)
    # Each program chunk processes 4*BLOCK elements (four keep bits per hash).
    num_chunks = triton.cdiv(N, 4 * BLOCK)

    # Cap the launched program count to a small multiple of the physical vector
    # core count (pure Vector kernel -> num_vectorcore, queried on the target so
    # it stays B2-portable) so mid-size tensors loop several times per program
    # and amortize per-program scalar setup, while large tensors still saturate.
    # Also respect the Ascend coreDim hardware limit of 65535.
    grid_cap = min(_num_vectorcore(input.device) * 16, 65535)
    grid = (min(num_chunks, grid_cap),)

    seed = _rng_seed(input.device)

    # 8-bit integer dropout threshold: keep when u8 > thr8, P(keep)=1-p.
    # thr8 = round(p * 256), clamped to [0, 255]. 8-bit resolution quantizes the
    # keep probability to ~1/256 (~4e-3), acceptable for the statistical check.
    thr8 = int(round(p * 256.0))
    if thr8 < 0:
        thr8 = 0
    elif thr8 > 0xFF:
        thr8 = 0xFF

    # Native-precision affine helps fp16 but not bf16 on this backend (profiled);
    # promote to fp32 for bf16/fp32, blend natively for fp16.
    native_affine = input.dtype == torch.float16

    # When N is an exact multiple of the per-chunk span (4*BLOCK) every lane of
    # every chunk is in-bounds, so the boundary mask can be dropped from the hot
    # loop. Otherwise use the masked path.
    masked = (N % (4 * BLOCK)) != 0

    alpha_dropout_inplace_kernel[grid](
        flat,
        N,
        num_chunks,
        thr8,
        a,
        b,
        seed,
        BLOCK=BLOCK,
        NATIVE_AFFINE=native_affine,
        MASKED=masked,
        num_warps=num_warps,
    )
    return input
